sp_widget.client_script:
api.controller = function($scope, $location) {

    var c = this;


    /* =========================================================
       INITIALIZE
       ========================================================= */

    c.data = c.data || {};

    c.data.applications =
        c.data.applications || [];

    c.data.drives =
        c.data.drives || [];


    c.filteredApplications = [];


    c.searchText = '';

    c.statusFilter = '';

    c.driveFilter = '';


    c.currentPage = 1;

    c.pageSize = 8;

    c.totalPages = 1;


    /* =========================================================
       EDIT MODAL STATE
       ========================================================= */

    c.showEditModal = false;

    c.selectedApplication = null;

    c.editForm = {

        status: '',

        eligibilityStatus: ''
    };

    c.isSaving = false;

    c.editSuccess = '';

    c.editError = '';


    /* =========================================================
       APPLY FILTERS
       ========================================================= */

    c.applyFilters = function() {

        var applications =
            c.data.applications || [];


        var search =
            (c.searchText || '')
            .toLowerCase()
            .trim();


        var status =
            (c.statusFilter || '')
            .toLowerCase()
            .trim();


        var drive =
            (c.driveFilter || '')
            .toLowerCase()
            .trim();


        var filtered = [];


        for (
            var i = 0;
            i < applications.length;
            i++
        ) {

            var application =
                applications[i];


            var matchesSearch = true;

            var matchesStatus = true;

            var matchesDrive = true;


            /* =================================================
               SEARCH
               ================================================= */

            if (search) {

                var searchText =

                    (application.applicationNumber || '') +
                    ' ' +
                    (application.studentName || '') +
                    ' ' +
                    (application.registerNumber || '') +
                    ' ' +
                    (application.branch || '') +
                    ' ' +
                    (application.company || '') +
                    ' ' +
                    (application.driveName || '') +
                    ' ' +
                    (application.jobRole || '') +
                    ' ' +
                    (application.status || '');


                searchText =
                    searchText
                    .toLowerCase();


                matchesSearch =
                    searchText.indexOf(
                        search
                    ) !== -1;
            }


            /* =================================================
               STATUS
               ================================================= */

            if (status) {

                var applicationStatus =
                    (
                        application.status ||
                        ''
                    )
                    .toLowerCase()
                    .trim();


                matchesStatus =
                    applicationStatus ===
                    status;
            }


            /* =================================================
               DRIVE
               ================================================= */

            if (drive) {

                var applicationDrive =
                    (
                        application.driveSysId ||
                        ''
                    )
                    .toLowerCase();


                matchesDrive =
                    applicationDrive ===
                    drive;
            }


            /* =================================================
               FINAL
               ================================================= */

            if (
                matchesSearch &&
                matchesStatus &&
                matchesDrive
            ) {

                filtered.push(
                    application
                );
            }
        }


        c.filteredApplications =
            filtered;


        c.currentPage = 1;


        c.calculatePagination();
    };


    /* =========================================================
       PAGINATION
       ========================================================= */

    c.calculatePagination = function() {

        var totalRecords =
            c.filteredApplications.length;


        c.totalPages =
            Math.max(
                1,
                Math.ceil(
                    totalRecords /
                    c.pageSize
                )
            );


        if (
            c.currentPage >
            c.totalPages
        ) {

            c.currentPage =
                c.totalPages;
        }


        if (
            c.currentPage < 1
        ) {

            c.currentPage = 1;
        }
    };


    /* =========================================================
       PAGE APPLICATIONS
       ========================================================= */

    c.getPageApplications = function() {

        var start =
            (
                c.currentPage - 1
            ) *
            c.pageSize;


        var end =
            start +
            c.pageSize;


        return c.filteredApplications.slice(
            start,
            end
        );
    };


    /* =========================================================
       NEXT PAGE
       ========================================================= */

    c.nextPage = function() {

        if (
            c.currentPage <
            c.totalPages
        ) {

            c.currentPage++;

            c.scrollToTop();
        }
    };


    /* =========================================================
       PREVIOUS PAGE
       ========================================================= */

    c.previousPage = function() {

        if (
            c.currentPage > 1
        ) {

            c.currentPage--;

            c.scrollToTop();
        }
    };


    /* =========================================================
       GO TO PAGE
       ========================================================= */

    c.goToPage = function(page) {

        if (
            page >= 1 &&
            page <= c.totalPages
        ) {

            c.currentPage =
                page;

            c.scrollToTop();
        }
    };


    /* =========================================================
       PAGE NUMBERS
       ========================================================= */

    c.getPageNumbers = function() {

        var pages = [];

        var total =
            c.totalPages;


        if (total <= 5) {

            for (
                var i = 1;
                i <= total;
                i++
            ) {

                pages.push(i);
            }

            return pages;
        }


        if (
            c.currentPage <= 3
        ) {

            return [
                1,
                2,
                3,
                4,
                5
            ];
        }


        if (
            c.currentPage >=
            total - 2
        ) {

            return [
                total - 4,
                total - 3,
                total - 2,
                total - 1,
                total
            ];
        }


        return [
            c.currentPage - 2,
            c.currentPage - 1,
            c.currentPage,
            c.currentPage + 1,
            c.currentPage + 2
        ];
    };


    /* =========================================================
       CLEAR FILTERS
       ========================================================= */

    c.clearFilters = function() {

        c.searchText = '';

        c.statusFilter = '';

        c.driveFilter = '';

        c.applyFilters();
    };


    /* =========================================================
       SEARCH
       ========================================================= */

    c.onSearchChange = function() {

        c.applyFilters();
    };


    /* =========================================================
       STATUS CHANGE
       ========================================================= */

    c.onStatusChange = function() {

        c.applyFilters();
    };


    /* =========================================================
       DRIVE CHANGE
       ========================================================= */

    c.onDriveChange = function() {

        c.applyFilters();
    };


    /* =========================================================
       EDIT PERMISSION
       ========================================================= */

    c.canEditApplication = function(application) {

        if (!application) {
            return false;
        }


        return application.canEdit === true;
    };


    /* =========================================================
       ROLE HELPERS
       ========================================================= */

    c.isAdmin = function() {

        return (
            c.data.userRole ===
            'placement_admin'
        );
    };


    c.isOfficer = function() {

        return (
            c.data.userRole ===
            'placement_officer'
        );
    };


    c.isInterviewer = function() {

        return (
            c.data.userRole ===
            'interviewer'
        );
    };


    c.isStudent = function() {

        return (
            c.data.userRole ===
            'student_user'
        );
    };


    /* =========================================================
       STATUS HELPERS
       ========================================================= */

    c.isApplied = function(application) {

        return (
            application &&
            (
                application.status ||
                ''
            )
            .toLowerCase()
            .trim() ===
            'applied'
        );
    };


    c.isShortlisted = function(application) {

        return (
            application &&
            (
                application.status ||
                ''
            )
            .toLowerCase()
            .trim() ===
            'shortlisted'
        );
    };


    c.isInterviewScheduled = function(application) {

        return (
            application &&
            (
                application.status ||
                ''
            )
            .toLowerCase()
            .trim() ===
            'interview scheduled'
        );
    };


    c.isSelected = function(application) {

        return (
            application &&
            (
                application.status ||
                ''
            )
            .toLowerCase()
            .trim() ===
            'selected'
        );
    };


    c.isOffered = function(application) {

        return (
            application &&
            (
                application.status ||
                ''
            )
            .toLowerCase()
            .trim() ===
            'offered'
        );
    };


    c.isRejected = function(application) {

        return (
            application &&
            (
                application.status ||
                ''
            )
            .toLowerCase()
            .trim() ===
            'rejected'
        );
    };


    /* =========================================================
       STATUS TEXT
       ========================================================= */

    c.getStatusText = function(application) {

        if (
            !application ||
            !application.status
        ) {

            return 'Applied';
        }


        return application.status;
    };


    /* =========================================================
       STATUS CLASS
       ========================================================= */

    c.getStatusClass = function(status) {

        var value =
            (status || '')
            .toLowerCase()
            .trim();


        if (
            value === 'shortlisted'
        ) {

            return 'shortlisted';
        }


        if (
            value === 'interview scheduled'
        ) {

            return 'interview';
        }


        if (
            value === 'selected'
        ) {

            return 'selected';
        }


        if (
            value === 'offered'
        ) {

            return 'offered';
        }


        if (
            value === 'rejected'
        ) {

            return 'rejected';
        }


        return 'applied';
    };


    /* =========================================================
       PROGRESS STEP
       ========================================================= */

    c.getProgressStep = function(status) {

        var value =
            (status || '')
            .toLowerCase()
            .trim();


        if (value === 'applied') {
            return 1;
        }


        if (value === 'shortlisted') {
            return 2;
        }


        if (value === 'interview scheduled') {
            return 3;
        }


        if (value === 'selected') {
            return 4;
        }


        if (value === 'offered') {
            return 5;
        }


        if (value === 'rejected') {
            return 2;
        }


        return 1;
    };


    /* =========================================================
       OPEN EDIT MODAL

       THIS IS THE IMPORTANT PART.
       ========================================================= */

    c.openEditModal = function(application) {

        console.log(
            'NEXORA: Opening edit modal',
            application
        );


        if (!application) {

            console.log(
                'NEXORA: Application object missing'
            );

            return;
        }


        if (!application.sys_id) {

            console.log(
                'NEXORA: Application sys_id missing',
                application
            );

            return;
        }


        if (
            application.canEdit !== true
        ) {

            console.log(
                'NEXORA: User cannot edit this application'
            );

            return;
        }


        /* =====================================================
           STORE SELECTED APPLICATION
           ===================================================== */

        c.selectedApplication =
            application;


        /* =====================================================
           POPULATE FORM

           These values are taken directly from the
           application object loaded by the Server Script.
           ===================================================== */

        c.editForm = {

            status:
                application.status ||
                'Applied',

            eligibilityStatus:
                application.eligibilityStatus ||
                'Pending'
        };


        console.log(
            'NEXORA: Edit form populated',
            c.editForm
        );


        /* =====================================================
           RESET MESSAGES
           ===================================================== */

        c.editError = '';

        c.editSuccess = '';

        c.isSaving = false;


        /* =====================================================
           OPEN
           ===================================================== */

        c.showEditModal = true;


        /* =====================================================
           STOP BACKGROUND SCROLL
           ===================================================== */

        try {

            document.body.style.overflow =
                'hidden';

        } catch (e) {

            console.log(
                'NEXORA: Could not lock body scroll'
            );
        }
    };


    /* =========================================================
       CLOSE EDIT MODAL
       ========================================================= */

    c.closeEditModal = function() {

        if (c.isSaving) {
            return;
        }


        c.showEditModal = false;


        c.selectedApplication =
            null;


        c.editForm = {

            status: '',

            eligibilityStatus: ''
        };


        c.editError = '';

        c.editSuccess = '';


        try {

            document.body.style.overflow =
                '';

        } catch (e) {
            /* Ignore */
        }
    };


    /* =========================================================
       SAVE APPLICATION
       ========================================================= */

    c.saveApplication = function() {

        console.log(
            'NEXORA: Save clicked'
        );


        /* =====================================================
           VALIDATE RECORD
           ===================================================== */

        if (
            !c.selectedApplication ||
            !c.selectedApplication.sys_id
        ) {

            c.editError =
                'Application record could not be identified.';

            return;
        }


        /* =====================================================
           VALIDATE STATUS
           ===================================================== */

        if (
            !c.editForm.status
        ) {

            c.editError =
                'Please select an application status.';

            return;
        }


        /* =====================================================
           VALIDATE ELIGIBILITY
           ===================================================== */

        if (
            !c.editForm.eligibilityStatus
        ) {

            c.editError =
                'Please select an eligibility status.';

            return;
        }


        /* =====================================================
           PERMISSION
           ===================================================== */

        if (
            !c.canEditApplication(
                c.selectedApplication
            )
        ) {

            c.editError =
                'You do not have permission to edit this application.';

            return;
        }


        /* =====================================================
           START SAVE
           ===================================================== */

        c.isSaving = true;

        c.editError = '';

        c.editSuccess = '';


        /* =====================================================
           SERVER REQUEST
           ===================================================== */

        c.server.get({

            action:
                'updateApplication',

            sys_id:
                c.selectedApplication.sys_id,

            status:
                c.editForm.status,

            eligibilityStatus:
                c.editForm.eligibilityStatus

        }).then(

            function(response) {

                console.log(
                    'NEXORA: Server response',
                    response
                );


                c.isSaving = false;


                var result =
                    response.data || {};


                /* =================================================
                   SUCCESS
                   ================================================= */

                if (
                    result.success === true
                ) {

                    /* =============================================
                       UPDATE SELECTED RECORD
                       ============================================= */

                    c.selectedApplication.status =
                        result.status ||
                        c.editForm.status;


                    c.selectedApplication.eligibilityStatus =
                        result.eligibilityStatus ||
                        c.editForm.eligibilityStatus;


                    /* =============================================
                       UPDATE STATUS CLASS
                       ============================================= */

                    c.selectedApplication.statusClass =
                        c.getStatusClass(
                            c.selectedApplication.status
                        );


                    /* =============================================
                       UPDATE PROGRESS
                       ============================================= */

                    c.selectedApplication.progressStep =
                        c.getProgressStep(
                            c.selectedApplication.status
                        );


                    /* =============================================
                       RECALCULATE COUNTS
                       ============================================= */

                    c.recalculateCounts();


                    /* =============================================
                       FILTER AGAIN
                       ============================================= */

                    c.applyFilters();


                    /* =============================================
                       SUCCESS MESSAGE
                       ============================================= */

                    c.editSuccess =
                        'Application updated successfully.';


                    /* =============================================
                       CLOSE AFTER 700 MS
                       ============================================= */

                    setTimeout(
                        function() {

                            $scope.$apply(
                                function() {

                                    c.closeEditModal();

                                }
                            );

                        },
                        700
                    );

                } else {

                    c.editError =
                        result.error ||
                        'Unable to update the application.';
                }

            },

            function(error) {

                console.log(
                    'NEXORA: Server error',
                    error
                );


                c.isSaving = false;


                c.editError =
                    'Unable to update the application. Please try again.';
            }
        );
    };


    /* =========================================================
       RECALCULATE COUNTS
       ========================================================= */

    c.recalculateCounts = function() {

        var applications =
            c.data.applications || [];


        var total = 0;

        var inProgress = 0;

        var selected = 0;

        var offered = 0;


        for (
            var i = 0;
            i < applications.length;
            i++
        ) {

            var application =
                applications[i];


            var status =
                (
                    application.status ||
                    ''
                )
                .toLowerCase()
                .trim();


            total++;


            if (
                status === 'applied' ||
                status === 'shortlisted' ||
                status === 'interview scheduled'
            ) {

                inProgress++;
            }


            if (
                status === 'selected'
            ) {

                selected++;
            }


            if (
                status === 'offered'
            ) {

                offered++;
            }
        }


        c.data.totalApplications =
            total;


        c.data.inProgressCount =
            inProgress;


        c.data.selectedCount =
            selected;


        c.data.offeredCount =
            offered;
    };


    /* =========================================================
       VIEW APPLICATION
       ========================================================= */

    c.viewApplication = function(application) {

        if (
            !application ||
            !application.sys_id
        ) {

            return;
        }


        $location.search({

            id:
                'application_details',

            sys_id:
                application.sys_id
        });
    };


    /* =========================================================
       VIEW DRIVE
       ========================================================= */

    c.viewDrive = function(application) {

        if (
            !application ||
            !application.driveSysId
        ) {

            return;
        }


        $location.search({

            id:
                'drive_details',

            sys_id:
                application.driveSysId
        });
    };


    /* =========================================================
       SCROLL TOP
       ========================================================= */

    c.scrollToTop = function() {

        try {

            window.scrollTo({

                top: 0,

                behavior: 'smooth'

            });

        } catch (e) {

            window.scrollTo(
                0,
                0
            );
        }
    };


    /* =========================================================
       RESULT INFORMATION
       ========================================================= */

    c.getResultStart = function() {

        if (
            c.filteredApplications.length === 0
        ) {

            return 0;
        }


        return (
            (
                c.currentPage - 1
            ) *
            c.pageSize
        ) + 1;
    };


    c.getResultEnd = function() {

        var end =
            c.currentPage *
            c.pageSize;


        return Math.min(
            end,
            c.filteredApplications.length
        );
    };


    c.getResultCount = function() {

        return c.filteredApplications.length;
    };


    /* =========================================================
       ESCAPE KEY
       ========================================================= */

    c.onModalKeydown = function(event) {

        if (
            event &&
            event.key === 'Escape' &&
            c.showEditModal &&
            !c.isSaving
        ) {

            c.closeEditModal();
        }
    };


    /* =========================================================
       INITIALIZE COUNTS
       ========================================================= */

    c.recalculateCounts();


    /* =========================================================
       INITIAL FILTER
       ========================================================= */

    c.applyFilters();


    /* =========================================================
       CLEANUP
       ========================================================= */

    $scope.$on(
        '$destroy',
        function() {

            try {

                document.body.style.overflow =
                    '';

            } catch (e) {
                /* Ignore */
            }
        }
    );

};

sp_widget.css:
/* ============================================================
   NEXORA — APPLICATION MANAGEMENT
   COMPLETE PROFESSIONAL SERVICE PORTAL CSS
   Matches the provided Applications HTML
   ============================================================ */


/* ============================================================
   ROOT / GLOBAL
   ============================================================ */

.placement-wrapper,
.placement-wrapper * {
    box-sizing: border-box;
}

.placement-wrapper {
    width: 87vw;
    min-height: calc(100vh - 72px);

    padding: 70px;

    background: #ffffff;

    font-family:
        Inter,
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Arial,
        sans-serif;

    color: #172b3f;
}


/* ============================================================
   HEADER
   ============================================================ */

.placement-header {
    position: relative;

    width: 100%;
    min-height: 205px;

    margin-bottom: 22px;
    padding: 34px;

    overflow: hidden;

    border-radius: 22px;

    background:
        linear-gradient(
            135deg,
            #17334b 0%,
            #1b3b55 55%,
            #244963 100%
        );

    color: #ffffff;

    box-shadow:
        0 16px 40px
        rgba(23, 51, 75, 0.16);
}


/* Decorative circle */

.placement-header::before {
    content: "";

    position: absolute;

    width: 285px;
    height: 285px;

    right: -110px;
    top: -145px;

    border-radius: 50%;

    background:
        rgba(255, 107, 91, 0.08);
}


.placement-header::after {
    content: "";

    position: absolute;

    width: 190px;
    height: 190px;

    right: 105px;
    bottom: -125px;

    border-radius: 50%;

    border:
        1px solid
        rgba(255, 255, 255, 0.08);
}


/* ============================================================
   HEADER CONTENT
   ============================================================ */

.header-content {
    position: relative;

    z-index: 2;

    width: 100%;

    min-height: 137px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 30px;
}


.header-title-section {
    min-width: 0;

    flex: 1;

    display: block;
}


.header-label {
    display: block;

    margin-bottom: 12px;

    font-size: 11px;

    line-height: 1.2;

    font-weight: 800;

    letter-spacing: 1.8px;

    text-transform: uppercase;

    color: #ff7465;
}


.header-title-section h1 {
    display: block;

    margin: 0 0 12px;

    font-size: 38px;

    line-height: 1.08;

    font-weight: 800;

    letter-spacing: -1px;

    color: #ffffff;
}


.header-title-section p {
    max-width: 690px;

    margin: 0;

    font-size: 13px;

    line-height: 1.65;

    color:
        rgba(255, 255, 255, 0.68);
}


/* ============================================================
   HEADER META
   ============================================================ */

.header-meta {
    position: relative;

    z-index: 3;

    flex-shrink: 0;

    display: flex;

    align-items: center;
}


.header-role {
    min-height: 46px;

    display: inline-flex;

    align-items: center;

    gap: 9px;

    padding: 10px 15px;

    border:
        1px solid
        rgba(255, 255, 255, 0.13);

    border-radius: 30px;

    background:
        rgba(255, 255, 255, 0.075);

    backdrop-filter: blur(10px);

    color:
        rgba(255, 255, 255, 0.82);

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 0.3px;
}


.header-role i {
    color: #ff7465;

    font-size: 15px;
}


/* ============================================================
   CONTEXT BANNER
   ============================================================ */

.nx-context-banner {
    width: 100%;

    min-height: 76px;

    display: flex;

    align-items: center;

    gap: 14px;

    padding: 14px 18px;

    margin-bottom: 18px;

    border:
        1px solid #e2e8ee;

    border-radius: 15px;

    background: #ffffff;

    box-shadow:
        0 7px 22px
        rgba(23, 43, 63, 0.045);
}


/* Context icon */

.context-icon {
    width: 43px;
    height: 43px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background: #fff0ed;

    color: #f27457;

    font-size: 17px;
}


/* Context content */

.context-content {
    flex: 1;

    min-width: 0;
}


.context-title {
    display: block;

    margin-bottom: 4px;

    font-size: 13px;

    line-height: 1.4;

    font-weight: 800;

    color: #243b50;
}


.context-description {
    font-size: 10px;

    line-height: 1.5;

    color: #8997a4;
}


.context-description strong {
    color: #43586d;

    font-weight: 800;
}


/* ============================================================
   ERROR STATE
   ============================================================ */

.nx-error-state {
    width: 100%;

    min-height: 150px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    gap: 10px;

    padding: 40px 25px;

    text-align: center;

    border:
        1px solid #f0dddd;

    border-radius: 17px;

    background:
        linear-gradient(
            180deg,
            #fffafa,
            #ffffff
        );

    color: #9b716d;
}


.nx-error-state i {
    width: 55px;
    height: 55px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 16px;

    background: #fff0ef;

    color: #d55b51;

    font-size: 21px;
}


.nx-error-state span {
    max-width: 650px;

    font-size: 12px;

    line-height: 1.6;

    color: #9b716d;
}


/* ============================================================
   SUMMARY GRID
   ============================================================ */

.nx-summary-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 16px;

    margin-bottom: 22px;
}


.nx-summary-card {
    min-height: 105px;

    display: flex;

    align-items: center;

    gap: 14px;

    padding: 19px;

    border:
        1px solid #e2e8ee;

    border-radius: 16px;

    background: #ffffff;

    box-shadow:
        0 7px 24px
        rgba(23, 43, 63, 0.045);

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}


.nx-summary-card:hover {
    transform: translateY(-2px);

    box-shadow:
        0 13px 30px
        rgba(23, 43, 63, 0.08);
}


/* ============================================================
   SUMMARY ICONS
   ============================================================ */

.nx-summary-icon {
    width: 45px;
    height: 45px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 13px;

    font-size: 17px;
}


.nx-summary-icon.total {
    background: #edf4fa;

    color: #315c7b;
}


.nx-summary-icon.progress {
    background: #fff6e9;

    color: #d18b25;
}


.nx-summary-icon.selected {
    background: #edf9f3;

    color: #2b9c68;
}


.nx-summary-icon.offered {
    background: #fff0ed;

    color: #f27457;
}


/* ============================================================
   SUMMARY CONTENT
   ============================================================ */

.nx-summary-content {
    min-width: 0;

    display: flex;

    flex-direction: column;

    gap: 4px;
}


.nx-summary-label {
    font-size: 10px;

    font-weight: 700;

    letter-spacing: 0.2px;

    color: #8190a0;
}


.nx-summary-value {
    font-size: 25px;

    line-height: 1;

    font-weight: 800;

    color: #1b3349;
}


/* ============================================================
   FILTER PANEL
   ============================================================ */

.nx-filter-panel {
    width: 100%;

    padding: 18px;

    margin-bottom: 15px;

    border:
        1px solid #e2e8ee;

    border-radius: 15px;

    background: #ffffff;

    box-shadow:
        0 6px 20px
        rgba(23, 43, 63, 0.035);
}


/* ============================================================
   FILTER HEADER
   ============================================================ */

.nx-filter-header {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

    margin-bottom: 15px;
}


.nx-filter-title {
    display: flex;

    align-items: center;

    gap: 7px;

    margin-bottom: 3px;

    font-size: 11px;

    font-weight: 800;

    color: #30485e;
}


.nx-filter-title i {
    color: #f27457;
}


.nx-filter-subtitle {
    font-size: 9px;

    color: #9aa6b1;
}


.nx-clear-filter {
    display: inline-flex;

    align-items: center;

    gap: 6px;

    min-height: 34px;

    padding: 0 11px;

    border:
        1px solid #e2e8ed;

    border-radius: 8px;

    background: #f7f9fa;

    color: #718394;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;

    transition:
        background 0.18s ease,
        color 0.18s ease,
        border-color 0.18s ease;
}


.nx-clear-filter:hover {
    background: #fff0ed;

    border-color: #ffd5ce;

    color: #e96552;
}


/* ============================================================
   FILTER GRID
   ============================================================ */

.nx-filter-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        minmax(280px, 2fr)
        minmax(170px, 1fr)
        minmax(220px, 1fr);

    gap: 13px;
}


.nx-filter-field {
    min-width: 0;
}


.nx-filter-field label {
    display: block;

    margin-bottom: 6px;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 0.4px;

    color: #718394;
}


/* ============================================================
   SEARCH INPUT
   ============================================================ */

.nx-input-wrapper {
    position: relative;

    width: 100%;
}


.nx-input-wrapper i {
    position: absolute;

    left: 13px;
    top: 50%;

    transform:
        translateY(-50%);

    color: #94a2af;

    font-size: 12px;

    pointer-events: none;
}


.nx-filter-input {
    width: 100%;

    height: 42px;

    padding:
        0 13px 0 37px;

    border:
        1px solid #dfe6ed;

    border-radius: 9px;

    outline: none;

    background: #fbfcfd;

    color: #263d51;

    font-size: 11px;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease;
}


.nx-filter-input::placeholder {
    color: #a2adb7;
}


.nx-filter-input:focus {
    border-color: #f27457;

    background: #ffffff;

    box-shadow:
        0 0 0 3px
        rgba(242, 116, 87, 0.08);
}


/* ============================================================
   SELECT
   ============================================================ */

.nx-filter-select {
    width: 100%;

    height: 42px;

    padding:
        0 32px 0 11px;

    border:
        1px solid #dfe6ed;

    border-radius: 9px;

    outline: none;

    background: #fbfcfd;

    color: #344b60;

    font-size: 10px;

    font-weight: 700;

    cursor: pointer;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}


.nx-filter-select:focus {
    border-color: #f27457;

    background: #ffffff;

    box-shadow:
        0 0 0 3px
        rgba(242, 116, 87, 0.08);
}


/* ============================================================
   RESULT BAR
   ============================================================ */

.nx-result-bar {
    width: 100%;

    min-height: 32px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    margin:
        2px 3px 12px;

    color: #8795a2;

    font-size: 10px;
}


.nx-result-info {
    font-size: 10px;

    color: #8795a2;
}


.nx-result-info strong {
    color: #233a4f;

    font-weight: 800;
}


/* ============================================================
   APPLICATION LIST
   ============================================================ */

.nx-application-list {
    width: 100%;

    display: flex;

    flex-direction: column;

    gap: 14px;
}


/* ============================================================
   APPLICATION CARD
   ============================================================ */

.nx-application-card {
    width: 100%;

    padding:
        21px 22px 18px;

    border:
        1px solid #e1e7ed;

    border-radius: 17px;

    background: #ffffff;

    box-shadow:
        0 7px 25px
        rgba(23, 43, 63, 0.045);

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        border-color 0.2s ease;
}


.nx-application-card:hover {
    transform: translateY(-2px);

    border-color: #d4dee7;

    box-shadow:
        0 14px 34px
        rgba(23, 43, 63, 0.075);
}


/* ============================================================
   CARD HEADER
   ============================================================ */

.nx-application-card-header {
    width: 100%;

    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    gap: 18px;
}


.nx-company-section {
    min-width: 0;

    display: flex;

    align-items: center;

    gap: 13px;
}


.nx-company-logo {
    width: 48px;
    height: 48px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 13px;

    background:
        linear-gradient(
            135deg,
            #17334b,
            #2b526e
        );

    color: #ffffff;

    font-size: 17px;

    font-weight: 800;

    text-transform: uppercase;
}


.nx-company-info {
    min-width: 0;
}


.nx-company-name {
    margin-bottom: 4px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;

    font-size: 16px;

    line-height: 1.2;

    font-weight: 800;

    color: #193249;
}


.nx-drive-name {
    max-width: 600px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;

    font-size: 11px;

    color: #82909e;
}


/* ============================================================
   STATUS BADGE
   ============================================================ */

.nx-status-badge {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    min-height: 29px;

    padding:
        7px 12px;

    border-radius: 30px;

    font-size: 9px;

    font-weight: 800;

    white-space: nowrap;
}


/* Applied */

.nx-status-badge.applied {
    color: #41627a;

    background: #eef4f8;
}


/* Shortlisted */

.nx-status-badge.shortlisted {
    color: #88631d;

    background: #fff6df;
}


/* Interview */

.nx-status-badge.interview {
    color: #356c93;

    background: #eaf5fc;
}


/* Selected */

.nx-status-badge.selected {
    color: #23744f;

    background: #eaf8f1;
}


/* Offered */

.nx-status-badge.offered {
    color: #b54f43;

    background: #fff0ed;
}


/* Rejected */

.nx-status-badge.rejected {
    color: #a14444;

    background: #fdeeee;
}


/* ============================================================
   CANDIDATE SECTION
   ============================================================ */

.nx-candidate-section {
    display: flex;

    align-items: center;

    gap: 11px;

    margin-top: 16px;

    padding:
        10px 12px;

    border:
        1px solid #edf1f4;

    border-radius: 11px;

    background: #f8fafc;
}


.nx-candidate-avatar {
    width: 34px;
    height: 34px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background: #e9eef3;

    color: #31536d;

    font-size: 12px;

    font-weight: 800;

    text-transform: uppercase;
}


.nx-candidate-info {
    min-width: 0;

    flex: 1;
}


.nx-candidate-name {
    margin-bottom: 4px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;

    font-size: 12px;

    font-weight: 800;

    color: #30485e;
}


.nx-candidate-meta {
    display: flex;

    flex-wrap: wrap;

    align-items: center;

    gap: 7px;
}


.nx-candidate-meta span {
    display: inline-flex;

    align-items: center;

    gap: 4px;

    padding:
        4px 7px;

    border-radius: 6px;

    background: #eef3f7;

    font-size: 8px;

    font-weight: 700;

    color: #718394;
}


.nx-candidate-meta i {
    font-size: 8px;

    color: #8999a7;
}


/* ============================================================
   APPLICATION DETAILS
   ============================================================ */

.nx-application-details {
    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 12px;

    margin-top: 17px;

    padding-top: 16px;

    border-top:
        1px solid #edf1f4;
}


.nx-detail-item {
    min-width: 0;
}


.nx-detail-label {
    display: block;

    margin-bottom: 6px;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 1px;

    color: #9aa6b1;
}


.nx-detail-value {
    display: block;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;

    font-size: 11px;

    font-weight: 700;

    color: #334b60;
}


/* ============================================================
   ELIGIBILITY
   ============================================================ */

.nx-eligibility-badge {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    min-height: 24px;

    padding:
        5px 9px;

    border-radius: 7px;

    font-size: 8px;

    font-weight: 800;
}


.nx-eligibility-badge.eligible {
    background: #eaf8f1;

    color: #23744f;
}


.nx-eligibility-badge.not-eligible {
    background: #fdeeee;

    color: #a14444;
}


.nx-eligibility-badge.pending {
    background: #fff6df;

    color: #88631d;
}


/* ============================================================
   APPLICATION JOURNEY
   ============================================================ */

.nx-journey {
    position: relative;

    width: 100%;

    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    margin-top: 21px;

    padding:
        4px 5px 0;
}


.nx-journey-line {
    position: absolute;

    left: 9%;

    right: 9%;

    top: 16px;

    height: 3px;

    border-radius: 10px;

    background: #e7edf1;

    z-index: 0;
}


/* ============================================================
   JOURNEY STEP
   ============================================================ */

.nx-journey-step {
    position: relative;

    z-index: 2;

    width: 20%;

    display: flex;

    flex-direction: column;

    align-items: center;

    gap: 7px;

    text-align: center;
}


.nx-journey-circle {
    width: 32px;
    height: 32px;

    display: flex;

    align-items: center;
    justify-content: center;

    border:
        2px solid #e2e8ed;

    border-radius: 50%;

    background: #ffffff;

    color: #a3adb7;

    font-size: 10px;

    transition:
        background 0.2s ease,
        border-color 0.2s ease,
        color 0.2s ease,
        box-shadow 0.2s ease;
}


.nx-journey-step span {
    font-size: 8px;

    font-weight: 700;

    color: #a3adb7;

    white-space: nowrap;
}


/* Active */

.nx-journey-step.active .nx-journey-circle {
    border-color: #f27457;

    background: #fff0ed;

    color: #f27457;
}


.nx-journey-step.active span {
    color: #52687a;
}


/* Current */

.nx-journey-step.current .nx-journey-circle {
    border-color: #f27457;

    background: #f27457;

    color: #ffffff;

    box-shadow:
        0 0 0 5px
        rgba(242, 116, 87, 0.10);
}


.nx-journey-step.current span {
    color: #e96552;

    font-weight: 800;
}


/* ============================================================
   APPLICATION FOOTER
   ============================================================ */

.nx-application-footer {
    width: 100%;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

    margin-top: 17px;

    padding-top: 14px;

    border-top:
        1px solid #edf1f4;
}


.nx-footer-left,
.nx-footer-right {
    display: flex;

    align-items: center;

    gap: 8px;
}


/* ============================================================
   VIEW BUTTON
   ============================================================ */

.nx-view-btn,
.nx-edit-btn {
    min-height: 35px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 7px;

    padding:
        0 12px;

    border-radius: 8px;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;

    transition:
        transform 0.18s ease,
        background 0.18s ease,
        color 0.18s ease,
        box-shadow 0.18s ease;
}


.nx-view-btn {
    border:
        1px solid #e2e8ed;

    background: #f5f7f9;

    color: #43596c;
}


.nx-view-btn:hover {
    background: #eaf0f4;

    color: #263f53;

    transform: translateY(-1px);
}


/* ============================================================
   EDIT BUTTON
   ============================================================ */

.nx-edit-btn {
    border: none;

    background:
        linear-gradient(
            135deg,
            #f27457,
            #ff806d
        );

    color: #ffffff;

    box-shadow:
        0 5px 13px
        rgba(242, 116, 87, 0.18);
}


.nx-edit-btn:hover {
    background:
        linear-gradient(
            135deg,
            #e96552,
            #f27457
        );

    color: #ffffff;

    transform: translateY(-1px);

    box-shadow:
        0 8px 18px
        rgba(242, 116, 87, 0.25);
}


/* ============================================================
   EMPTY STATE
   ============================================================ */

.nx-empty-state {
    width: 100%;

    padding:
        70px 25px;

    text-align: center;

    border:
        1px dashed #dbe3e9;

    border-radius: 17px;

    background: #ffffff;

    box-shadow:
        0 6px 22px
        rgba(23, 43, 63, 0.025);
}


.nx-empty-icon {
    width: 60px;
    height: 60px;

    display: flex;

    align-items: center;
    justify-content: center;

    margin:
        0 auto 16px;

    border-radius: 18px;

    background: #f1f5f8;

    color: #8091a0;

    font-size: 22px;
}


.nx-empty-state h3 {
    margin:
        0 0 7px;

    font-size: 16px;

    color: #294156;
}


.nx-empty-state p {
    max-width: 500px;

    margin:
        0 auto 18px;

    font-size: 12px;

    line-height: 1.7;

    color: #8997a4;
}


/* ============================================================
   EMPTY BUTTON
   ============================================================ */

.nx-empty-button {
    min-height: 38px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 7px;

    padding:
        0 14px;

    border:
        1px solid #dfe6ed;

    border-radius: 9px;

    background: #f5f7f9;

    color: #43596c;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;

    transition:
        background 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}


.nx-empty-button:hover {
    background: #fff0ed;

    color: #e96552;

    transform: translateY(-1px);
}


/* ============================================================
   PAGINATION
   ============================================================ */

.nx-pagination {
    display: flex;

    align-items: center;
    justify-content: center;

    gap: 6px;

    margin-top: 22px;

    padding:
        5px;
}


.nx-page-arrow,
.nx-page-number {
    min-width: 34px;
    height: 34px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    border:
        1px solid #e1e7ed;

    border-radius: 8px;

    background: #ffffff;

    color: #647789;

    font-size: 10px;

    font-weight: 800;

    cursor: pointer;

    transition:
        background 0.18s ease,
        color 0.18s ease,
        border-color 0.18s ease,
        transform 0.18s ease;
}


.nx-page-arrow:hover:not(:disabled),
.nx-page-number:hover {
    background: #f5f8fa;

    border-color: #d5dee6;

    color: #29475d;

    transform: translateY(-1px);
}


.nx-page-number.active {
    border-color: #17334b;

    background: #17334b;

    color: #ffffff;

    box-shadow:
        0 5px 12px
        rgba(23, 51, 75, 0.16);
}


.nx-page-arrow:disabled {
    opacity: 0.4;

    cursor: not-allowed;
}


/* ============================================================
   EDIT MODAL OVERLAY
   ============================================================ */

.nx-modal-overlay {
    position: fixed;

    top: 0;
    left: 0;
    right: 0;
    bottom: 0;

    z-index: 99999;

    display: flex;

    align-items: center;
    justify-content: center;

    padding: 25px;

    background:
        rgba(11, 27, 41, 0.62);

    backdrop-filter: blur(5px);

    animation:
        nx-modal-fade-in 0.2s ease;
}


@keyframes nx-modal-fade-in {

    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }

}


/* ============================================================
   APPLICATION MODAL
   ============================================================ */

.nx-application-modal {
    width: 100%;

    max-width: 850px;

    max-height: 92vh;

    display: flex;

    flex-direction: column;

    overflow: hidden;

    border-radius: 20px;

    background: #ffffff;

    box-shadow:
        0 30px 80px
        rgba(8, 25, 39, 0.30);

    animation:
        nx-modal-slide-up 0.25s ease;
}


@keyframes nx-modal-slide-up {

    from {
        opacity: 0;

        transform:
            translateY(18px)
            scale(0.985);
    }

    to {
        opacity: 1;

        transform:
            translateY(0)
            scale(1);
    }

}


/* ============================================================
   MODAL HEADER
   ============================================================ */

.nx-modal-header {
    position: relative;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding:
        23px 25px;

    background:
        linear-gradient(
            135deg,
            #17334b 0%,
            #1b3b55 55%,
            #244963 100%
        );

    color: #ffffff;
}


.nx-modal-header-content {
    display: flex;

    align-items: center;

    gap: 14px;

    min-width: 0;
}


.nx-modal-icon {
    width: 45px;
    height: 45px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 13px;

    background:
        rgba(255, 107, 91, 0.15);

    color: #ff806d;

    font-size: 16px;
}


.nx-modal-eyebrow {
    margin-bottom: 4px;

    font-size: 8px;

    line-height: 1.2;

    font-weight: 800;

    letter-spacing: 1.4px;

    color: #ff806d;
}


.nx-modal-header h2 {
    margin:
        0 0 4px;

    font-size: 21px;

    line-height: 1.2;

    font-weight: 800;

    color: #ffffff;
}


.nx-modal-header p {
    margin: 0;

    font-size: 10px;

    line-height: 1.5;

    color:
        rgba(255, 255, 255, 0.63);
}


/* ============================================================
   MODAL CLOSE
   ============================================================ */

.nx-modal-close {
    width: 34px;
    height: 34px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border:
        1px solid
        rgba(255, 255, 255, 0.14);

    border-radius: 9px;

    background:
        rgba(255, 255, 255, 0.07);

    color:
        rgba(255, 255, 255, 0.72);

    font-size: 13px;

    cursor: pointer;

    transition:
        background 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}


.nx-modal-close:hover:not(:disabled) {
    background:
        rgba(255, 107, 91, 0.18);

    color: #ffffff;

    transform: rotate(3deg);
}


.nx-modal-close:disabled {
    opacity: 0.5;

    cursor: not-allowed;
}


/* ============================================================
   MODAL BODY
   ============================================================ */

.nx-modal-body {
    flex: 1;

    min-height: 0;

    overflow-y: auto;

    padding:
        22px 25px 24px;

    background:
        #ffffff;
}


/* Custom scrollbar */

.nx-modal-body::-webkit-scrollbar {
    width: 7px;
}


.nx-modal-body::-webkit-scrollbar-track {
    background: #f5f7f9;
}


.nx-modal-body::-webkit-scrollbar-thumb {
    border-radius: 20px;

    background: #ccd6de;
}


.nx-modal-body::-webkit-scrollbar-thumb:hover {
    background: #b7c4ce;
}


/* ============================================================
   MODAL SUCCESS
   ============================================================ */

.nx-modal-success {
    display: flex;

    align-items: center;

    gap: 9px;

    margin-bottom: 16px;

    padding:
        11px 13px;

    border:
        1px solid #ccebdc;

    border-radius: 10px;

    background: #effaf4;

    color: #23744f;

    font-size: 10px;

    font-weight: 700;
}


.nx-modal-success i {
    font-size: 14px;
}


/* ============================================================
   MODAL ERROR
   ============================================================ */

.nx-modal-error {
    display: flex;

    align-items: center;

    gap: 9px;

    margin-bottom: 16px;

    padding:
        11px 13px;

    border:
        1px solid #f1d2cf;

    border-radius: 10px;

    background: #fff5f4;

    color: #a14444;

    font-size: 10px;

    font-weight: 700;
}


.nx-modal-error i {
    font-size: 14px;
}


/* ============================================================
   APPLICATION SUMMARY
   ============================================================ */

.nx-modal-application-summary {
    display: flex;

    align-items: center;

    gap: 13px;

    padding:
        14px;

    margin-bottom: 20px;

    border:
        1px solid #e4eaf0;

    border-radius: 13px;

    background:
        linear-gradient(
            180deg,
            #fbfcfd,
            #f7f9fb
        );
}


.nx-modal-company-icon {
    width: 46px;
    height: 46px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background:
        linear-gradient(
            135deg,
            #17334b,
            #2b526e
        );

    color: #ffffff;

    font-size: 15px;

    font-weight: 800;
}


.nx-modal-company-info {
    min-width: 0;

    flex: 1;
}


.nx-modal-company-name {
    margin-bottom: 4px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;

    font-size: 14px;

    font-weight: 800;

    color: #20394f;
}


.nx-modal-drive-name {
    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;

    font-size: 9px;

    color: #8493a0;
}


.nx-modal-application-id {
    flex-shrink: 0;

    display: flex;

    flex-direction: column;

    align-items: flex-end;

    gap: 4px;

    padding-left: 15px;

    border-left:
        1px solid #e1e7ed;
}


.nx-modal-application-id span {
    font-size: 7px;

    font-weight: 800;

    letter-spacing: 1px;

    color: #9aa6b1;
}


.nx-modal-application-id strong {
    font-size: 10px;

    font-weight: 800;

    color: #42596d;
}


/* ============================================================
   MODAL SECTION
   ============================================================ */

.nx-modal-section {
    margin-bottom: 21px;
}


.nx-modal-section:last-child {
    margin-bottom: 0;
}


.nx-modal-section-title {
    display: flex;

    align-items: center;

    gap: 7px;

    margin-bottom: 11px;

    padding-bottom: 8px;

    border-bottom:
        1px solid #edf1f4;

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 0.3px;

    color: #334b60;
}


.nx-modal-section-title i {
    color: #f27457;

    font-size: 11px;
}


/* ============================================================
   MODAL GRID
   ============================================================ */

.nx-modal-grid {
    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 14px;
}


.nx-modal-field {
    min-width: 0;
}


.nx-modal-field label {
    display: block;

    margin-bottom: 6px;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 0.8px;

    color: #7d8d9b;
}


.nx-modal-field label .required {
    color: #f27457;

    margin-left: 2px;
}


/* ============================================================
   READONLY FIELD
   ============================================================ */

.nx-readonly-field {
    width: 100%;

    min-height: 40px;

    display: flex;

    align-items: center;

    gap: 8px;

    padding:
        0 11px;

    overflow: hidden;

    border:
        1px solid #e2e8ed;

    border-radius: 9px;

    background: #f6f8fa;

    color: #53687a;

    font-size: 10px;

    font-weight: 700;

    white-space: nowrap;

    text-overflow: ellipsis;
}


.nx-readonly-field i {
    flex-shrink: 0;

    color: #92a0ad;

    font-size: 10px;
}


/* ============================================================
   MODAL SELECT
   ============================================================ */

.nx-modal-select {
    width: 100%;

    height: 40px;

    padding:
        0 32px 0 11px;

    border:
        1px solid #dfe6ed;

    border-radius: 9px;

    outline: none;

    background: #ffffff;

    color: #30485e;

    font-size: 10px;

    font-weight: 700;

    cursor: pointer;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}


.nx-modal-select:hover {
    border-color: #cfd9e1;
}


.nx-modal-select:focus {
    border-color: #f27457;

    box-shadow:
        0 0 0 3px
        rgba(242, 116, 87, 0.08);
}


/* ============================================================
   MODAL INFORMATION BOX
   ============================================================ */

.nx-modal-info {
    display: flex;

    align-items: flex-start;

    gap: 11px;

    margin-top: 4px;

    padding:
        12px 14px;

    border:
        1px solid #d7e9f4;

    border-radius: 11px;

    background: #f3f9fd;

    color: #356c93;
}


.nx-modal-info > i {
    flex-shrink: 0;

    margin-top: 2px;

    font-size: 14px;
}


.nx-modal-info strong {
    display: block;

    margin-bottom: 3px;

    font-size: 10px;

    font-weight: 800;

    color: #356c93;
}


.nx-modal-info p {
    margin: 0;

    font-size: 9px;

    line-height: 1.5;

    color: #6f8799;
}


/* Rejected */

.nx-modal-info.rejected {
    border-color: #f0d6d4;

    background: #fff6f5;

    color: #a14444;
}


.nx-modal-info.rejected strong {
    color: #a14444;
}


.nx-modal-info.rejected > i {
    color: #d55b51;
}


/* Selected */

.nx-modal-info.selected {
    border-color: #ccebdc;

    background: #f2faf6;

    color: #23744f;
}


.nx-modal-info.selected strong {
    color: #23744f;
}


.nx-modal-info.selected > i {
    color: #2b9c68;
}


/* ============================================================
   MODAL FOOTER
   ============================================================ */

.nx-modal-footer {
    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: flex-end;

    gap: 9px;

    padding:
        15px 25px;

    border-top:
        1px solid #e8edf1;

    background: #fbfcfd;
}


/* ============================================================
   MODAL CANCEL
   ============================================================ */

.nx-modal-cancel {
    min-height: 38px;

    padding:
        0 15px;

    border:
        1px solid #dfe6ed;

    border-radius: 9px;

    background: #ffffff;

    color: #53697b;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;

    transition:
        background 0.18s ease,
        border-color 0.18s ease,
        color 0.18s ease;
}


.nx-modal-cancel:hover:not(:disabled) {
    background: #f4f7f9;

    border-color: #d2dce4;

    color: #30485e;
}


/* ============================================================
   MODAL SAVE
   ============================================================ */

.nx-modal-save {
    min-height: 38px;

    min-width: 125px;

    padding:
        0 16px;

    border: none;

    border-radius: 9px;

    background:
        linear-gradient(
            135deg,
            #f27457,
            #ff806d
        );

    color: #ffffff;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;

    box-shadow:
        0 5px 14px
        rgba(242, 116, 87, 0.18);

    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease,
        background 0.18s ease;
}


.nx-modal-save:hover:not(:disabled) {
    transform: translateY(-1px);

    background:
        linear-gradient(
            135deg,
            #e96552,
            #f27457
        );

    box-shadow:
        0 8px 18px
        rgba(242, 116, 87, 0.25);
}


.nx-modal-save:disabled,
.nx-modal-cancel:disabled {
    opacity: 0.55;

    cursor: not-allowed;

    transform: none;
}


.nx-modal-save i {
    margin-right: 5px;
}


/* ============================================================
   FOCUS
   ============================================================ */

.nx-view-btn:focus,
.nx-edit-btn:focus,
.nx-clear-filter:focus,
.nx-empty-button:focus,
.nx-page-arrow:focus,
.nx-page-number:focus,
.nx-modal-close:focus,
.nx-modal-cancel:focus,
.nx-modal-save:focus,
.nx-filter-input:focus,
.nx-filter-select:focus,
.nx-modal-select:focus {
    outline:
        2px solid
        rgba(242, 116, 87, 0.25);

    outline-offset: 2px;
}


/* ============================================================
   TABLET — 1100px
   ============================================================ */

@media (max-width: 1100px) {

    .placement-wrapper {
        width: 100%;

        padding:
            30px 25px 50px;
    }


    .nx-summary-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }


    .nx-filter-grid {
        grid-template-columns:
            minmax(220px, 1.5fr)
            minmax(170px, 1fr);
    }


    .nx-filter-field.search-field {
        grid-column:
            1 / -1;
    }


    .nx-application-details {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }

}


/* ============================================================
   SMALL TABLET — 900px
   ============================================================ */

@media (max-width: 900px) {

    .placement-header {
        min-height: 190px;

        padding: 30px;
    }


    .header-content {
        align-items: flex-start;

        justify-content: center;

        flex-direction: column;

        gap: 20px;
    }


    .header-meta {
        position: absolute;

        right: 28px;

        top: 50%;

        transform:
            translateY(-50%);
    }


    .header-title-section {
        max-width: 70%;
    }


    .header-title-section h1 {
        font-size: 34px;
    }


    .nx-filter-grid {
        grid-template-columns:
            1fr 1fr;
    }


    .nx-filter-field.search-field {
        grid-column:
            1 / -1;
    }


    .nx-application-card-header {
        align-items: flex-start;
    }


    .nx-modal-overlay {
        padding: 18px;
    }


    .nx-application-modal {
        max-height: 94vh;
    }

}


/* ============================================================
   MOBILE — 700px
   ============================================================ */

@media (max-width: 700px) {

    .placement-wrapper {
        width: 100%;

        padding:
            18px 14px 40px;
    }


    /* Header */

    .placement-header {
        min-height: auto;

        padding:
            27px 21px;

        border-radius: 17px;
    }


    .header-content {
        min-height: auto;

        align-items: flex-start;

        gap: 18px;
    }


    .header-title-section {
        width: 100%;

        max-width: 100%;
    }


    .header-title-section h1 {
        font-size: 30px;
    }


    .header-title-section p {
        font-size: 12px;
    }


    .header-meta {
        position: static;

        transform: none;
    }


    .header-role {
        width: auto;
    }


    /* Context */

    .nx-context-banner {
        align-items: flex-start;
    }


    /* Summary */

    .nx-summary-grid {
        grid-template-columns: 1fr;
    }


    /* Filter */

    .nx-filter-header {
        align-items: flex-start;

        flex-direction: column;
    }


    .nx-clear-filter {
        width: 100%;
    }


    .nx-filter-grid {
        grid-template-columns: 1fr;
    }


    .nx-filter-field.search-field {
        grid-column: auto;
    }


    /* Card */

    .nx-application-card {
        padding:
            18px 16px;
    }


    .nx-application-card-header {
        flex-direction: column;

        gap: 12px;
    }


    .nx-status-badge {
        align-self: flex-start;
    }


    .nx-company-name {
        font-size: 15px;
    }


    /* Candidate */

    .nx-candidate-section {
        align-items: flex-start;
    }


    .nx-candidate-meta {
        flex-direction: column;

        align-items: flex-start;

        gap: 4px;
    }


    /* Details */

    .nx-application-details {
        grid-template-columns: 1fr;
    }


    /* Journey */

    .nx-journey {
        padding-left: 0;

        padding-right: 0;
    }


    .nx-journey-line {
        left: 8%;

        right: 8%;
    }


    .nx-journey-circle {
        width: 29px;
        height: 29px;

        font-size: 9px;
    }


    .nx-journey-step span {
        font-size: 7px;
    }


    /* Footer */

    .nx-application-footer {
        align-items: stretch;

        flex-direction: column;
    }


    .nx-footer-left,
    .nx-footer-right {
        width: 100%;
    }


    .nx-view-btn,
    .nx-edit-btn {
        flex: 1;

        width: 100%;
    }


    /* Pagination */

    .nx-pagination {
        overflow-x: auto;

        justify-content: flex-start;

        padding-bottom: 8px;
    }


    /* Modal */

    .nx-modal-overlay {
        align-items: flex-end;

        padding: 0;
    }


    .nx-application-modal {
        width: 100%;

        max-width: none;

        max-height: 95vh;

        border-radius:
            20px 20px 0 0;
    }


    .nx-modal-header {
        padding:
            19px 18px;
    }


    .nx-modal-header h2 {
        font-size: 18px;
    }


    .nx-modal-header p {
        font-size: 9px;
    }


    .nx-modal-body {
        padding:
            18px;
    }


    .nx-modal-footer {
        padding:
            13px 18px;
    }


    .nx-modal-grid {
        grid-template-columns: 1fr;
    }


    .nx-modal-application-summary {
        flex-wrap: wrap;
    }


    .nx-modal-application-id {
        width: 100%;

        align-items: flex-start;

        padding:
            10px 0 0;

        border-left: none;

        border-top:
            1px solid #e1e7ed;
    }

}


/* ============================================================
   SMALL MOBILE — 560px
   ============================================================ */

@media (max-width: 560px) {

    .placement-wrapper {
        padding:
            15px 11px 35px;
    }


    .placement-header {
        padding:
            24px 18px;
    }


    .header-title-section h1 {
        font-size: 27px;
    }


    .header-label {
        font-size: 10px;

        letter-spacing: 1.5px;
    }


    .header-role {
        width: 100%;

        justify-content: center;
    }


    .nx-context-banner {
        flex-wrap: wrap;
    }


    .context-content {
        width:
            calc(100% - 57px);
    }


    .nx-summary-card {
        min-height: 92px;

        padding: 16px;
    }


    .nx-filter-panel {
        padding: 13px;
    }


    .nx-application-card {
        padding:
            16px 14px;
    }


    .nx-company-logo {
        width: 43px;
        height: 43px;
    }


    .nx-company-name {
        font-size: 14px;
    }


    .nx-application-footer {
        gap: 10px;
    }


    .nx-footer-left,
    .nx-footer-right {
        flex-direction: column;

        width: 100%;
    }


    .nx-view-btn,
    .nx-edit-btn {
        width: 100%;

        flex: none;
    }


    .nx-journey-step span {
        font-size: 6.5px;
    }


    .nx-journey-circle {
        width: 27px;
        height: 27px;
    }


    .nx-modal-header-content {
        gap: 10px;
    }


    .nx-modal-icon {
        width: 40px;
        height: 40px;
    }


    .nx-modal-close {
        width: 31px;
        height: 31px;
    }


    .nx-modal-header h2 {
        font-size: 17px;
    }


    .nx-modal-header p {
        display: none;
    }


    .nx-modal-footer {
        flex-direction: column-reverse;

        align-items: stretch;
    }


    .nx-modal-cancel,
    .nx-modal-save {
        width: 100%;
    }

}


/* ============================================================
   VERY SMALL MOBILE — 400px
   ============================================================ */

@media (max-width: 400px) {

    .placement-wrapper {
        padding:
            12px 9px 30px;
    }


    .placement-header {
        padding:
            22px 16px;
    }


    .header-title-section h1 {
        font-size: 24px;
    }


    .nx-summary-content strong {
        font-size: 22px;
    }


    .nx-modal-body {
        padding:
            15px;
    }


    .nx-modal-header {
        padding:
            17px 15px;
    }


    .nx-modal-footer {
        padding:
            12px 15px;
    }

}


/* ============================================================
   REDUCED MOTION
   ============================================================ */

@media (prefers-reduced-motion: reduce) {

    .placement-wrapper *,
    .placement-wrapper *::before,
    .placement-wrapper *::after {
        scroll-behavior: auto !important;

        transition: none !important;

        animation: none !important;
    }

}


/* ============================================================
   ANGULAR / SERVICENOW SAFETY
   ============================================================ */

.placement-wrapper button {
    font-family: inherit;
}


.placement-wrapper input,
.placement-wrapper select,
.placement-wrapper button {
    box-shadow: none;
}


.placement-wrapper input:disabled,
.placement-wrapper select:disabled,
.placement-wrapper button:disabled {
    cursor: not-allowed;
}


/* ============================================================
   END — NEXORA APPLICATION MANAGEMENT CSS
   ============================================================ */

sp_widget.script:
(function() {

    /* =========================================================
       NEXORA APPLICATIONS
       ROLE-BASED APPLICATION ACCESS

       TABLES
       ---------------------------------------------------------
       Application:
       x_snc_college_pl_0_application

       Student:
       x_snc_college_pl_0_student

       Placement Drive:
       x_snc_college_pl_0_placement_drive

       Interview:
       x_snc_college_pl_0_interview

       Company:
       x_snc_college_pl_0_company


       ACTUAL REFERENCE RELATIONSHIP
       ---------------------------------------------------------

       Application
            |
            | drive
            v
       Placement Drive
            |
            | company
            v
       Company
            |
            | hr_user
            v
       sys_user


       INTERVIEWER ACCESS RULE
       ---------------------------------------------------------

       Current logged-in interviewer
                    |
                    v
       x_snc_college_pl_0_company.hr_user
                    |
                    v
       Company
                    |
                    v
       Placement Drive
                    |
                    v
       Application


       Therefore:

       Interviewer sees ONLY applications where:

       application.drive.company.hr_user
                       =
       current logged-in user


       STUDENT
       ---------------------------------------------------------
       Student sees only their own applications.


       PLACEMENT OFFICER
       ---------------------------------------------------------
       Officer sees all applications.
       Officer cannot edit.


       PLACEMENT ADMIN
       ---------------------------------------------------------
       Admin sees all applications.
       Admin can edit.


       INTERVIEWER
       ---------------------------------------------------------
       Interviewer sees applications belonging to drives
       whose company's hr_user is the current interviewer.

       Interviewer can edit only those applications.
       ========================================================= */


    /* =========================================================
       INITIAL DATA
       ========================================================= */

    data.applications = [];
    data.drives = [];

    data.totalApplications = 0;
    data.inProgressCount = 0;
    data.selectedCount = 0;
    data.offeredCount = 0;

    data.userRole = '';
    data.roleLabel = '';
    data.totalLabel = '';
    data.assignedDriveName = '';

    data.canEditApplications = false;

    data.error = '';

    data.success = false;
    data.status = '';
    data.eligibilityStatus = '';


    /* =========================================================
       CURRENT USER
       ========================================================= */

    var currentUserId = gs.getUserID();


    /* =========================================================
       ROLE CHECK
       ========================================================= */

    function hasApplicationRole(roleName) {

        if (gs.hasRole(roleName)) {
            return true;
        }

        if (
            gs.hasRole(
                'x_snc_college_pl_0.' + roleName
            )
        ) {
            return true;
        }

        return false;
    }


    /* =========================================================
       ROLE FLAGS
       ========================================================= */

    var isAdmin =
        gs.hasRole('admin') ||
        hasApplicationRole('placement_admin');

    var isPlacementOfficer =
        hasApplicationRole('placement_officer');

    var isInterviewer =
        hasApplicationRole('interviewer');

    var isStudent =
        hasApplicationRole('student_user');


    /* =========================================================
       ROLE PRIORITY
       ========================================================= */

    if (isAdmin) {

        data.userRole = 'placement_admin';

        data.roleLabel =
            'Placement Admin';

        data.totalLabel =
            'All Student Applications';

        data.canEditApplications =
            true;

    } else if (isPlacementOfficer) {

        data.userRole =
            'placement_officer';

        data.roleLabel =
            'Placement Officer';

        data.totalLabel =
            'All Student Applications';

        data.canEditApplications =
            false;

    } else if (isInterviewer) {

        data.userRole =
            'interviewer';

        data.roleLabel =
            'Interviewer';

        data.totalLabel =
            'Assigned Drive Applications';

        data.canEditApplications =
            true;

    } else if (isStudent) {

        data.userRole =
            'student_user';

        data.roleLabel =
            'Student';

        data.totalLabel =
            'My Applications';

        data.canEditApplications =
            false;

    } else {

        data.userRole =
            'unauthorized';

        data.roleLabel =
            'Unauthorized';

        data.totalLabel =
            'No Application Access';

        data.canEditApplications =
            false;

        data.error =
            'Your current role does not have access to the Applications module.';

        return;
    }


    /* =========================================================
       INTERVIEWER ACCESS HELPER

       This uses the EXACT relationship:

       Placement Drive.company.hr_user

       It collects the Placement Drive IDs belonging to
       the currently logged-in interviewer.
       ========================================================= */

    function getInterviewerAccess() {

        var result = {

            driveIds: [],

            driveNames: [],

            applicationIds: []
        };


        /* =====================================================
           ADD UNIQUE DRIVE
           ===================================================== */

        function addDrive(
            driveId,
            driveName
        ) {

            if (!driveId) {
                return;
            }

            var exists = false;


            for (
                var i = 0;
                i < result.driveIds.length;
                i++
            ) {

                if (
                    result.driveIds[i] ===
                    driveId
                ) {

                    exists = true;
                    break;
                }
            }


            if (!exists) {

                result.driveIds.push(
                    driveId
                );

                result.driveNames.push(
                    driveName || driveId
                );
            }
        }


        /* =====================================================
           PRIMARY INTERVIEWER ACCESS

           Company table:
           x_snc_college_pl_0_company

           Field:
           hr_user

           Relationship:

           Company.hr_user
                  ↓
           current user

           Then:

           Placement Drive.company
                  ↓
           Company
           ===================================================== */

        var placementDriveGR =
            new GlideRecord(
                'x_snc_college_pl_0_placement_drive'
            );


        /*
         * IMPORTANT:
         *
         * We are directly dot-walking:
         *
         * company.hr_user
         *
         * from the Placement Drive table.
         *
         * This avoids manually querying core_company.
         */

        placementDriveGR.addQuery(
            'company.hr_user',
            currentUserId
        );

        placementDriveGR.orderBy(
            'company'
        );

        placementDriveGR.orderBy(
            'drive_name'
        );

        placementDriveGR.query();


        while (
            placementDriveGR.next()
        ) {

            addDrive(

                placementDriveGR.getUniqueValue(),

                placementDriveGR.getDisplayValue(
                    'drive_name'
                )
            );
        }


        /* =====================================================
           OPTIONAL DIRECT INTERVIEW ACCESS

           This does NOT replace the company.hr_user rule.

           It only records the specific application assigned
           to the current interviewer through an Interview record.

           This is useful when an Interview already exists for
           the interviewer but the application/drive relationship
           needs to be retained for edit authorization.

           IMPORTANT:
           The main application visibility remains based on:

           application.drive.company.hr_user
           ===================================================== */

        var interviewGR =
            new GlideRecord(
                'x_snc_college_pl_0_interview'
            );


        if (
            interviewGR.isValidField(
                'interviewer'
            )
        ) {

            interviewGR.addQuery(
                'interviewer',
                currentUserId
            );

            interviewGR.query();


            while (
                interviewGR.next()
            ) {

                var interviewApplicationId =
                    interviewGR.getValue(
                        'application'
                    );


                if (
                    interviewApplicationId
                ) {

                    var applicationGR =
                        new GlideRecord(
                            'x_snc_college_pl_0_application'
                        );


                    if (
                        applicationGR.get(
                            interviewApplicationId
                        )
                    ) {

                        result.applicationIds.push(
                            applicationGR.getUniqueValue()
                        );
                    }
                }
            }
        }


        return result;
    }


    /* =========================================================
       INTERVIEWER ACCESS DATA
       ========================================================= */

    var interviewerAccess = null;


    if (
        data.userRole ===
        'interviewer'
    ) {

        interviewerAccess =
            getInterviewerAccess();


        if (
            interviewerAccess.driveNames.length > 0
        ) {

            data.assignedDriveName =
                interviewerAccess.driveNames.join(
                    ', '
                );

        } else {

            data.assignedDriveName =
                'No Assigned Placement Drive';
        }
    }


    /* =========================================================
       UPDATE APPLICATION
       ========================================================= */

    if (
        input &&
        input.action ===
        'updateApplication'
    ) {

        data.success = false;

        data.error = '';


        var updateSysId =
            input.sys_id;

        var updateStatus =
            input.status;

        var updateEligibility =
            input.eligibilityStatus;


        /* =====================================================
           PERMISSION
           ===================================================== */

        if (
            !isAdmin &&
            !isInterviewer
        ) {

            data.error =
                'You do not have permission to edit applications.';

            return;
        }


        /* =====================================================
           SYS ID VALIDATION
           ===================================================== */

        if (
            !updateSysId
        ) {

            data.error =
                'Application record was not specified.';

            return;
        }


        /* =====================================================
           STATUS VALIDATION
           ===================================================== */

        if (
            !updateStatus
        ) {

            data.error =
                'Application status is required.';

            return;
        }


        /* =====================================================
           ELIGIBILITY VALIDATION
           ===================================================== */

        if (
            !updateEligibility
        ) {

            data.error =
                'Eligibility status is required.';

            return;
        }


        /* =====================================================
           GET APPLICATION
           ===================================================== */

        var updateGR =
            new GlideRecord(
                'x_snc_college_pl_0_application'
            );


        if (
            !updateGR.get(
                updateSysId
            )
        ) {

            data.error =
                'Application record could not be found.';

            return;
        }


        /* =====================================================
           INTERVIEWER AUTHORIZATION

           Primary authorization:

           Application.drive
                    ↓
           Placement Drive.company
                    ↓
           Company.hr_user
                    ↓
           current user
           ===================================================== */

        if (
            isInterviewer &&
            !isAdmin
        ) {

            var applicationAuthorized =
                false;


            /* =================================================
               DIRECT APPLICATION ASSIGNMENT

               If this application already has an Interview
               record assigned to the current interviewer,
               allow that application.
               ================================================= */

            if (
                interviewerAccess &&
                interviewerAccess.applicationIds.indexOf(
                    updateSysId
                ) !== -1
            ) {

                applicationAuthorized =
                    true;
            }


            /* =================================================
               PRIMARY DRIVE AUTHORIZATION
               ================================================= */

            var applicationDrive =
                updateGR.getValue(
                    'drive'
                );


            if (
                !applicationAuthorized &&
                applicationDrive &&
                interviewerAccess &&
                interviewerAccess.driveIds.indexOf(
                    applicationDrive
                ) !== -1
            ) {

                applicationAuthorized =
                    true;
            }


            /* =================================================
               DENY
               ================================================= */

            if (
                !applicationAuthorized
            ) {

                data.error =
                    'You are not authorized to edit this application.';

                return;
            }
        }


        /* =====================================================
           ALLOWED APPLICATION STATUS
           ===================================================== */

        var allowedStatuses = {

            'Applied': true,

            'Shortlisted': true,

            'Interview Scheduled': true,

            'Selected': true,

            'Rejected': true,

            'Offered': true
        };


        if (
            !allowedStatuses[
                updateStatus
            ]
        ) {

            data.error =
                'Invalid application status.';

            return;
        }


        /* =====================================================
           ALLOWED ELIGIBILITY STATUS
           ===================================================== */

        var allowedEligibility = {

            'Eligible': true,

            'Not Eligible': true,

            'Pending': true
        };


        if (
            !allowedEligibility[
                updateEligibility
            ]
        ) {

            data.error =
                'Invalid eligibility status.';

            return;
        }


        /* =====================================================
           UPDATE APPLICATION
           ===================================================== */

        updateGR.setValue(
            'status',
            updateStatus
        );

        updateGR.setValue(
            'eligibility_status',
            updateEligibility
        );


        var updatedSysId =
            updateGR.update();


        if (
            !updatedSysId
        ) {

            data.error =
                'Application could not be updated.';

            return;
        }


        /* =====================================================
           SUCCESS RESPONSE
           ===================================================== */

        data.success =
            true;


        data.status =
            updateGR.getDisplayValue(
                'status'
            );


        data.eligibilityStatus =
            updateGR.getDisplayValue(
                'eligibility_status'
            );


        return;
    }


    /* =========================================================
       APPLICATION TABLE
       ========================================================= */

    var applicationGR =
        new GlideRecord(
            'x_snc_college_pl_0_application'
        );


    /* =========================================================
       STUDENT ACCESS
       ========================================================= */

    if (
        data.userRole ===
        'student_user'
    ) {

        applicationGR.addQuery(
            'student.user',
            currentUserId
        );
    }


    /* =========================================================
       INTERVIEWER ACCESS

       THIS IS THE IMPORTANT PART.

       Exact relationship:

       Application
          ↓ drive
       Placement Drive
          ↓ company
       Company
          ↓ hr_user
       Current Interviewer
       ========================================================= */
/* =========================================================
   INTERVIEWER ACCESS

   Interviewer can see applications when EITHER:

   1. Application.drive.company.hr_user
      = current logged-in interviewer

   OR

   2. Application is directly assigned to the
      current interviewer through an Interview record.
   ========================================================= */

if (
    data.userRole ===
    'interviewer'
) {

    var interviewerApplicationQuery =
        applicationGR.addQuery(
            'drive.company.hr_user',
            currentUserId
        );

    if (
        interviewerAccess &&
        interviewerAccess.applicationIds.length > 0
    ) {

        interviewerApplicationQuery.addOrCondition(
            'sys_id',
            'IN',
            interviewerAccess.applicationIds.join(',')
        );
    }
}
    /* =========================================================
       ORDER APPLICATIONS
       ========================================================= */

    applicationGR.orderByDesc(
        'application_date'
    );


    applicationGR.query();


    /* =========================================================
       BUILD APPLICATION DATA
       ========================================================= */

    while (
        applicationGR.next()
    ) {

        var application = {};


        /* =====================================================
           APPLICATION BASIC DETAILS
           ===================================================== */

        application.sys_id =
            applicationGR.getUniqueValue();


        application.applicationNumber =
            applicationGR.getValue(
                'application_number'
            ) ||
            applicationGR.getUniqueValue();


        application.appliedDate =
            applicationGR.getDisplayValue(
                'application_date'
            );


        application.status =
            applicationGR.getDisplayValue(
                'status'
            );


        application.eligibilityStatus =
            applicationGR.getDisplayValue(
                'eligibility_status'
            );


        /* =====================================================
           STUDENT DETAILS
           ===================================================== */

        if (
            applicationGR.student
        ) {

            var studentGR =
                applicationGR.student.getRefRecord();


            if (
                studentGR &&
                studentGR.isValidRecord()
            ) {

                application.studentName =
                    studentGR.getDisplayValue(
                        'student_name'
                    );


                application.studentInitial =
                    (
                        application.studentName ||
                        'S'
                    )
                    .charAt(0)
                    .toUpperCase();


                application.registerNumber =
                    studentGR.getDisplayValue(
                        'register_number'
                    );


                application.branch =
                    studentGR.getDisplayValue(
                        'branch'
                    );
            }
        }


        /* =====================================================
           FALLBACK STUDENT DISPLAY
           ===================================================== */

        if (
            !application.studentName
        ) {

            application.studentName =
                applicationGR.getDisplayValue(
                    'student'
                );


            application.studentInitial =
                (
                    application.studentName ||
                    'S'
                )
                .charAt(0)
                .toUpperCase();
        }


        /* =====================================================
           DRIVE SYS ID
           ===================================================== */

        application.driveSysId =
            applicationGR.getValue(
                'drive'
            );


        /* =====================================================
           DRIVE DETAILS
           ===================================================== */

        if (
            applicationGR.drive
        ) {

            var driveGR =
                applicationGR.drive.getRefRecord();


            if (
                driveGR &&
                driveGR.isValidRecord()
            ) {

                application.driveName =
                    driveGR.getDisplayValue(
                        'drive_name'
                    );


                application.company =
                    driveGR.getDisplayValue(
                        'company'
                    );


                application.jobRole =
                    driveGR.getDisplayValue(
                        'job_role'
                    );
            }
        }


        /* =====================================================
           FALLBACK DRIVE NAME
           ===================================================== */

        if (
            !application.driveName
        ) {

            application.driveName =
                applicationGR.getDisplayValue(
                    'drive'
                );
        }


        /* =====================================================
           DEFAULT COMPANY / JOB ROLE
           ===================================================== */

        application.company =
            application.company || '';


        application.jobRole =
            application.jobRole || '';


        application.companyInitial =
            (
                application.company ||
                'C'
            )
            .charAt(0)
            .toUpperCase();


        /* =====================================================
           STATUS CLASS
           ===================================================== */

        var statusValue =
            (
                application.status ||
                ''
            )
            .toLowerCase()
            .trim();


        if (
            statusValue ===
            'shortlisted'
        ) {

            application.statusClass =
                'shortlisted';

        } else if (
            statusValue ===
            'interview scheduled'
        ) {

            application.statusClass =
                'interview';

        } else if (
            statusValue ===
            'selected'
        ) {

            application.statusClass =
                'selected';

        } else if (
            statusValue ===
            'offered'
        ) {

            application.statusClass =
                'offered';

        } else if (
            statusValue ===
            'rejected'
        ) {

            application.statusClass =
                'rejected';

        } else {

            application.statusClass =
                'applied';
        }


        /* =====================================================
           PROGRESS STEP
           ===================================================== */

        if (
            statusValue ===
            'applied'
        ) {

            application.progressStep =
                1;

        } else if (
            statusValue ===
            'shortlisted'
        ) {

            application.progressStep =
                2;

        } else if (
            statusValue ===
            'interview scheduled'
        ) {

            application.progressStep =
                3;

        } else if (
            statusValue ===
            'selected'
        ) {

            application.progressStep =
                4;

        } else if (
            statusValue ===
            'offered'
        ) {

            application.progressStep =
                5;

        } else if (
            statusValue ===
            'rejected'
        ) {

            application.progressStep =
                2;

        } else {

            application.progressStep =
                1;
        }


        /* =====================================================
           SUMMARY COUNTS
           ===================================================== */

        data.totalApplications++;


        if (
            statusValue === 'applied' ||
            statusValue === 'shortlisted' ||
            statusValue === 'interview scheduled'
        ) {

            data.inProgressCount++;
        }


        if (
            statusValue ===
            'selected'
        ) {

            data.selectedCount++;
        }


        if (
            statusValue ===
            'offered'
        ) {

            data.offeredCount++;
        }


        /* =====================================================
           EDIT PERMISSION
           ===================================================== */

        application.canEdit =
            data.canEditApplications;


        /* =====================================================
           ADD APPLICATION
           ===================================================== */

        data.applications.push(
            application
        );
    }


    /* =========================================================
       ADMIN + OFFICER DRIVE FILTER DATA
       ========================================================= */

    if (
        data.userRole ===
            'placement_admin' ||
        data.userRole ===
            'placement_officer'
    ) {

        var driveGR2 =
            new GlideRecord(
                'x_snc_college_pl_0_placement_drive'
            );


        driveGR2.orderBy(
            'company'
        );


        driveGR2.orderBy(
            'drive_name'
        );


        driveGR2.query();


        while (
            driveGR2.next()
        ) {

            data.drives.push({

                sys_id:
                    driveGR2.getUniqueValue(),

                company:
                    driveGR2.getDisplayValue(
                        'company'
                    ),

                driveName:
                    driveGR2.getDisplayValue(
                        'drive_name'
                    )
            });
        }
    }


})();
